instances.schema:
type Student {
  id: ID!
  name: String!
  email: String
  major: String!
  year: Int
  advisor: Faculty
  enrollments: [Enrollment]
}

type Enrollment {
  semester: String!
  grade: String
  course: Course!
}

type Course {
  code: String!
  title: String!
  credits: Int!
  level: String
  department: String
  instructor: Faculty
}

type Faculty {
  id: ID!
  name: String!
  department: String!
  courses: [Course]
}

input StudentFilter {
  major: String
  year: Int
  minGpa: Float
}

type Query {
  students(
    filter: StudentFilter
    first: Int
    after: String
  ): [Student]

  instructor(id: ID!): Faculty
}

instances.graphql_query:
query CourseEnrollment(
  $showEmail: Boolean!
) {
  csStudents: students(
    filter: { major: "CS", year: 3 }
    first: 10
  ) {
    name
    email @include(if: $showEmail)
    enrollments {
      semester
      grade
      course {
        ...CourseFields
        instructor {
          name
          department
        }
      }
    }
  }
}

fragment CourseFields on Course {
  code
  title
  credits
  department
}
